/*
 * File generated by an automated process on 2023-11-15.
 */
const fileSys = require('node:fs');

let totalSize = fileSys.fstatSync(process.stdin.fd).size;

const dataBuffer = Buffer.alloc(totalSize);

let bytesProcessed = fileSys.readSync(process.stdin.fd, dataBuffer, 0, totalSize, 0);

const dataLines = dataBuffer.toString('utf8', 0, bytesProcessed).split('\n');

programEntry();

// Function to construct a 2D array (grid) initialized with a specific value.
function createGrid (rowsCount, columnsCount, initialFill) {
  let twoDArray = [];
  let rIdx, cIdx;

  for (rIdx = 0; rIdx < rowsCount; rIdx++) {
    twoDArray[rIdx] = [];
    for (cIdx = 0; cIdx < columnsCount; cIdx++) {
      twoDArray[rIdx][cIdx] = initialFill;
    }
  }
  return twoDArray;
}

/*
 * Computes the maximum possible score for a given target melody length
 * using a list of available musical segments.
 */
function calculateMaxScore(targetMelodyLength, segmentCollection) {
  const numSegments = segmentCollection.length;
  // Initialize a dynamic programming table.
  let scoreTable = createGrid(numSegments + 1, targetMelodyLength + 1, 0);
  let segIdx, currentLength;
  let segmentStartPoint, segmentDuration, segmentValue;
  let relevantScores;

  // Iterate through each segment and each possible melody length.
  for (segIdx = 0; segIdx < numSegments; segIdx++) {
    for (currentLength = 0; currentLength <= targetMelodyLength; currentLength++) {
      // Extract properties of the current segment: start, duration, points.
      segmentStartPoint = segmentCollection[segIdx][0];
      segmentDuration   = segmentCollection[segIdx][1];
      segmentValue      = segmentCollection[segIdx][2];

      // Check if the segment's start point is within the current melody length.
      if (segmentStartPoint <= currentLength) {
        // Calculate the relevant slice of previous scores.
        relevantScores = scoreTable[segIdx + 1].slice(
          segmentDuration > currentLength ? 0 : currentLength - segmentDuration,
          currentLength - segmentStartPoint + 1
        );
        // Update the DP table: either keep previous score or take current segment for a better score.
        scoreTable[segIdx + 1][currentLength] = Math.max(
          scoreTable[segIdx][currentLength],
          Math.max.apply(null, relevantScores) + segmentValue
        );
      } else {
        // If segment cannot start, carry over the score from the previous row.
        scoreTable[segIdx + 1][currentLength] = scoreTable[segIdx][currentLength];
      }
    }
  }
  // The final result is in the bottom-right corner of the table.
  return scoreTable[numSegments][targetMelodyLength];
}

// The main entry point for the program execution.
function programEntry() {

  // Read the number of musical segments from input.
  let segmentCount = Number(dataLines.shift());
  let segmentCollection = [];

  // Populate the list of musical segments.
  for (let currentSegmentIdx = 0; currentSegmentIdx < segmentCount; currentSegmentIdx++) {
    segmentCollection.push(dataLines.shift().split(' ').map(val => parseInt(val, 10)));
  }

  /*
   * The following commented-out block demonstrates an alternative approach
   * involving sorting segments, which is not used in the final logic.
   *
   * // segmentCount = segmentCollection.length;
   * // segmentCollection.sort(function (itemA, itemB) {
   * //   return itemA[2] - itemB[2];
   * // });
   * // console.log(segmentCollection);
   */

  // Read the number of target melody lengths.
  let numTargetMelodies = Number(dataLines.shift());
  let tuneValues = [];
  let currentTuneLength;
  let finalScores = [];
  let melodyProcIdx; // Loop index for processing melodies
  let currentMaxScoreAchieved;
  let hasValidResult = true;

  // Populate the list of target melody lengths.
  for (melodyProcIdx = 0; melodyProcIdx < numTargetMelodies; melodyProcIdx++) {
    tuneValues.push(Number(dataLines.shift()));
  }

  // Process each target melody length.
  for (melodyProcIdx = 0; melodyProcIdx < numTargetMelodies; melodyProcIdx++) {
    currentTuneLength = tuneValues[melodyProcIdx];
    // Calculate the maximum possible score for the current melody length.
    currentMaxScoreAchieved = calculateMaxScore(currentTuneLength, segmentCollection);

    // Check if a valid score was found.
    if (currentMaxScoreAchieved === 0) {
      hasValidResult = false;
    } else {
      finalScores.push(currentMaxScoreAchieved);
    }
  }

  // Output results.
  if (!hasValidResult) {
    console.log(-1);
    return;
  }
  finalScores.forEach(function(scoreOutput){
    console.log(scoreOutput);
  });

}